changeSet.sql:
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE organizations FORCE ROW LEVEL SECURITY;

CREATE POLICY organizations_platform ON organizations FOR ALL
    USING (current_setting('landvault.platform_scope', true) = 'on')
    WITH CHECK (current_setting('landvault.platform_scope', true) = 'on');

CREATE POLICY organizations_tenant ON organizations FOR ALL
    USING (
        current_setting('landvault.tenant_id', true) IS NOT NULL
        AND current_setting('landvault.tenant_id', true) != ''
        AND id::text = current_setting('landvault.tenant_id', true)
    )
    WITH CHECK (
        current_setting('landvault.tenant_id', true) IS NOT NULL
        AND current_setting('landvault.tenant_id', true) != ''
        AND id::text = current_setting('landvault.tenant_id', true)
    );

changeSet.rollback:
DROP POLICY IF EXISTS organizations_platform ON organizations;
DROP POLICY IF EXISTS organizations_tenant ON organizations;
ALTER TABLE organizations NO FORCE ROW LEVEL SECURITY;
ALTER TABLE organizations DISABLE ROW LEVEL SECURITY;
